"use client";

import { useState } from "react";
import toast from "react-hot-toast";
import { Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useEntitlementError } from "@/hooks/useEntitlementError";
import type { MatchExplanation } from "@/helpers/matching/schemas";
import { cn } from "@/utils/utils";

const FOOTNOTE =
  "Generated by AI from the candidate's profile and resume. Verify before deciding.";

function Section({ title, items }: { title: string; items: string[] }) {
  if (items.length === 0) return null;
  return (
    <section aria-label={title} className="flex flex-col gap-1">
      <h4 className="text-sm font-semibold">{title}</h4>
      <ul className="list-disc pl-5 text-sm text-muted-foreground space-y-0.5">
        {items.map((item, i) => (
          <li key={i}>{item}</li>
        ))}
      </ul>
    </section>
  );
}

/**
 * "Why this candidate" (MT-REQ-003/004): strengths, gaps and conflicts for one
 * candidate and job. Without a stored explanation it offers to generate one,
 * which may use the plan's match explanations.
 */
export default function MatchExplanationCard({
  jobPostId,
  candidateId,
  explanation: initial,
  compact = false,
  className,
}: {
  jobPostId: string;
  candidateId: string;
  explanation: MatchExplanation | null | undefined;
  /** A small "Why?" button for list cards; the full card otherwise. */
  compact?: boolean;
  className?: string;
}) {
  const [explanation, setExplanation] = useState(initial ?? null);
  const [loading, setLoading] = useState(false);
  const { handle: handleEntitlement, dialog } = useEntitlementError();

  const explain = async () => {
    setLoading(true);
    try {
      const res = await fetch("/api/company/matches/explain", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ jobPostId, candidateId }),
      });
      if (await handleEntitlement(res)) return;
      const body = await res.json().catch(() => null);
      if (!res.ok || !body?.explanation) {
        toast.error(body?.error ?? "Couldn't explain this match. Please try again.");
        return;
      }
      setExplanation(body.explanation);
    } catch {
      toast.error("Couldn't explain this match. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const content = explanation && (
    <div className="flex flex-col gap-3">
      <p className="text-sm">{explanation.summary}</p>
      <Section title="Strengths" items={explanation.strengths} />
      <Section title="Gaps" items={explanation.gaps} />
      <Section title="Conflicts" items={explanation.conflicts} />
    </div>
  );

  const button = !explanation && (
    <Button
      type="button"
      variant="outline"
      size={compact ? "sm" : "default"}
      onClick={explain}
      disabled={loading}
      className="self-start"
    >
      {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
      {compact ? "Why?" : "Why this match?"}
    </Button>
  );

  const footnote = <p className="text-xs text-muted-foreground">{FOOTNOTE}</p>;

  if (compact) {
    return (
      <div className={cn("flex flex-col gap-2", className)}>
        {button}
        {content && (
          <div className="rounded-lg border p-3 flex flex-col gap-3">
            {content}
            {footnote}
          </div>
        )}
        {dialog}
      </div>
    );
  }

  return (
    <div className={cn("rounded-lg border p-4 flex flex-col gap-3", className)}>
      <h3 className="font-semibold">Why this candidate</h3>
      {content}
      {button}
      {footnote}
      {dialog}
    </div>
  );
}
